const LABOUR_DESC = {"14-01":"Site establishment","14-02":"Setting out / survey","14-03":"Excavation labour","14-04":"Earth removal / cart away","14-05":"Foundation labour","14-06":"Concrete placing labour","14-07":"Steel fixing labour","14-08":"Bricklaying labour","14-09":"Roof truss installation","14-10":"Roof tiling labour","14-11":"Roof sheeting labour","14-12":"Ceiling installation labour","14-13":"Plumbing installation labour","14-14":"Electrical installation labour","14-15":"Plastering labour","14-16":"Screeding labour","14-17":"Tiling labour","14-18":"Painting labour","14-19":"Door and window installation","14-20":"Waterproofing labour","14-21":"Paving labour","14-22":"Rubble removal","14-23":"Delivery charge","14-24":"Crane / offloading charge","14-25":"Plant hire / mixer","14-26":"Scaffolding hire","14-27":"Building inspection / compliance service","14-28":"Engineer / professional service","14-29":"Other service (describe in comments)"}
const COSAVE_SLUG = 'cosave-powerbuild'
export const AVERAGE_SLUG = 'average'

const cache = {}
const withVat = (p) => Math.round(p * 1.15 * 100) / 100

function mkItem(code, description, unit, price, brand, spec, verified) {
  return { code, description, quantity: null, unit, price, priceInclVat: withVat(price), verified: !!verified, brand: brand || '', spec: spec || '' }
}

function finish(key, name, categories, extra) {
  // Labour is shared by every supplier list.
  categories[13].items = LABOUR.map(([code, , unit, price]) => mkItem(code, LABOUR_DESC[code], unit, price, '', '', false))
  const items = []
  categories.forEach((c) => c.items.forEach((it) => items.push({ ...it, category: c.category })))
  const record = {
    supplier: name,
    fileName: 'GnA Fast Quote price list (built in)',
    uploadedAt: '2026-10-27T00:00:00.000Z',
    uploadedBy: 'built-in demo data',
    categories,
    items,
    totalItems: items.length,
    isBuiltIn: true,
    ...extra
  }
  cache[key] = record
  return record
}

const emptyCategories = () => CATEGORY_NAMES.map((category) => ({ category, items: [] }))

function standardList(key) {
  const prices = PRICES[key]
  const verified = VERIFIED[key] || {}
  const categories = emptyCategories()
  MASTER.forEach(([code, cat, description, unit]) => {
    const v = verified[code]
    categories[cat].items.push(mkItem(code, description, unit, prices[code], v && v[0], v && v[1], !!v))
  })
  ;(EXTRAS[key] || []).forEach(([code, cat, description, unit, price, brand, spec]) => {
    categories[cat].items.push(mkItem(code, description, unit, price, brand, spec, true))
  })
  return finish(key, 'Built-in demo price list', categories, {
    verifiedItems: Object.keys(verified).length + (EXTRAS[key] || []).length
  })
}

function cosaveList() {
  const categories = emptyCategories()
  const rates = {}
  COSAVE.forEach(([cat, line, description, unit, price, brand, spec]) => {
    categories[cat].items.push(mkItem('CP-' + String(cat + 1).padStart(2, '0') + '-' + String(line).padStart(3, '0'), description, unit, price, brand, spec, true))
  })
  Object.keys(COSAVE_RATES).forEach((k) => { rates[k] = COSAVE_RATES[k] })
  return finish(COSAVE_SLUG, 'Cosave Powerbuild & Wholesalers price list', categories, {
    verifiedItems: COSAVE.length,
    // Plan items are priced from this map; anything not in it has no Cosave equivalent.
    rates,
    ratesOnly: true
  })
}

function averageList() {
  const categories = emptyCategories()
  const lists = Object.keys(PRICES)
  let priced = 0
  MASTER.forEach(([code, cat, description, unit]) => {
    const vals = lists.map((k) => PRICES[k][code]).filter((p) => typeof p === 'number')
    if (COSAVE_RATES[code] !== undefined) vals.push(COSAVE_RATES[code])
    const avg = Math.round((vals.reduce((a, b) => a + b, 0) / vals.length) * 100) / 100
    priced += 1
    categories[cat].items.push(mkItem(code, description, unit, avg, '', 'Average of ' + vals.length + ' supplier prices', false))
  })
  return finish(AVERAGE_SLUG, 'Average estimate across all six suppliers', categories, { verifiedItems: 0, isAverage: true })
}

export function getDefaultPriceList(slug) {
  const key = slug === COSAVE_SLUG || slug === AVERAGE_SLUG || PRICES[slug] ? slug : 'buco'
  if (cache[key]) return cache[key]
  if (key === COSAVE_SLUG) return cosaveList()
  if (key === AVERAGE_SLUG) return averageList()
  return standardList(key)
}

// Cosave's own rates for the plan's master codes (used when a Cosave list is uploaded without them).
export function getCosaveRates() {
  return { ...COSAVE_RATES }
}

// For an admin-uploaded Cosave list (items coded "CP-<sheet>-<line>"): the rate for each plan item that has a Cosave equivalent.
export function cosaveRatesFromItems(items) {
  const byCode = {}
  ;(items || []).forEach((it) => { byCode[String(it.code)] = it.price })
  const rates = {}
  Object.keys(COSAVE_MAP).forEach((k) => {
    const p = byCode['CP-' + COSAVE_MAP[k]]
    if (typeof p === 'number') rates[k] = p
  })
  return rates
}
